import pandas as pd, re, math

def extract_annual(file, sheet):
    df = pd.read_excel(file, sheet_name=sheet, header=None)
    years=[]
    vals=[]
    for idx, val in df[0].items():
        if isinstance(val, (int, float)):
            if isinstance(val, float) and math.isnan(val):
                continue
            year=int(val)
            if 1800<year<2100:
                years.append(year)
                vals.append(df.loc[idx,1])
        elif isinstance(val, str):
            m = re.fullmatch(r"\s*(\d{4})\.?\s*", val)
            if m:
                year=int(m.group(1))
                years.append(year)
                vals.append(df.loc[idx,1])
    return years, vals

for f,s in [('/root/ERP-2025-table10.xls','B10'),('/root/ERP-2025-table12.xls','B12')]:
    years, vals = extract_annual(f,s)
    print(f, 'annual count', len(years), 'min', min(years), 'max', max(years))
    print('last few', list(zip(years[-5:], vals[-5:])))
